            if ($c < $minChar) {
                $minChar = $c;
                $minIndex = $i;
            }
        }
    }

    if ($minIndex !== -1) {
        // Remove the character at minIndex
        array_splice($chars, $minIndex, 1);
        $n--;
        $count++;
        $changed = true;
    }
}

echo $count . "\n";
?>
